@push('styles')
<style>
.privacy-policy{color:#292722}.privacy-policy h2{font-size:clamp(24px,3vw,34px);margin-bottom:18px;color:#171717}.privacy-policy p,.privacy-policy li{font-size:16px;line-height:1.85}.privacy-policy section{scroll-margin-top:140px;padding-bottom:32px;margin-bottom:32px;border-bottom:1px solid #d9d2c4}.privacy-policy a{color:#705820;text-decoration:underline;text-underline-offset:4px}.privacy-index{position:sticky;top:130px;border-left:2px solid #b89a5c;padding-left:24px}.privacy-index a{display:block;padding:10px 0;font-size:14px}.privacy-policy a:focus-visible{outline:2px solid #705820;outline-offset:4px}.privacy-note{padding:24px;border:1px solid #d9d2c4;background:#fff;margin-bottom:36px}.privacy-policy :last-child{overflow-wrap:anywhere}
